import styled from '@emotion/styled';
import { theme } from 'theme';

export const StyledDeepDiveBreakdownViewContainer = styled.div({
  borderRadius: '16px',
  border: '1px solid #1414141F',
  margin: theme.spacing['6'],
  marginTop: '0',
  marginBottom: '24px',
});

export const StyledDeepDiveRankingViewContainer = styled.div({
  borderRadius: '16px',
  border: '1px solid #1414141F',
  margin: theme.spacing['6'],
  marginTop: '0',
  marginBottom: '0',
  height: 'fit-content',
  minHeight: '200px',
  display: 'flex',
  flexDirection: 'column',
});
